-- Clinical case bank for the Case Challenge, authored in the case studio
-- (/manage/cases) instead of TypeScript files in the repository.
--
-- One row per case:
--   * published - the MedicalCase JSON students play (null until first publish)
--   * draft     - unpublished work: a new case, or changes to a published one
-- Publishing copies draft -> published and clears draft. `version` guards
-- against two editors overwriting each other's drafts.
--
-- All access goes through server functions using the service role, like the
-- rest of the app; the anon/authenticated roles get nothing.
--
-- The previous v1 `public.cases` table is left untouched: v1 attempts,
-- challenges and leaderboards still reference it.

CREATE TABLE IF NOT EXISTS public.clinical_cases (
  id uuid PRIMARY KEY,
  slug text NOT NULL UNIQUE,
  published jsonb,
  draft jsonb,
  sort_order integer NOT NULL DEFAULT 1000,
  version integer NOT NULL DEFAULT 1,
  created_by uuid REFERENCES public.app_users(id) ON DELETE SET NULL,
  updated_by uuid REFERENCES public.app_users(id) ON DELETE SET NULL,
  published_by uuid REFERENCES public.app_users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT clinical_cases_slug_format CHECK (slug ~ '^[a-z0-9_]{1,48}$'),
  CONSTRAINT clinical_cases_has_content CHECK (published IS NOT NULL OR draft IS NOT NULL)
);

CREATE INDEX IF NOT EXISTS clinical_cases_published_order
  ON public.clinical_cases (sort_order, published_at)
  WHERE published IS NOT NULL;

ALTER TABLE public.clinical_cases ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.clinical_cases FROM anon, authenticated;
GRANT ALL ON public.clinical_cases TO service_role;

-- Case images. Public so students' browsers can load them directly; writes
-- happen only through signed upload URLs issued by the studio's server
-- functions (content-creator allowlist), so no insert policy is granted.
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES (
  'case-images',
  'case-images',
  true,
  10485760,
  ARRAY['image/jpeg', 'image/png', 'image/webp', 'image/gif']
)
ON CONFLICT (id) DO UPDATE SET
  public = true,
  file_size_limit = EXCLUDED.file_size_limit,
  allowed_mime_types = EXCLUDED.allowed_mime_types;

