  ('a1000000-0000-4000-8000-000000000001', 'case_001', '{"id":"a1000000-0000-4000-8000-000000000001","slug":"case_001","title":"The Long Flight","difficulty":2,"specialty":["Emergency","Pulmonology"],"setting":"ER, 2:47 AM","intro":"ER, 2:47 AM. A 34-year-old woman is wheeled in by her husband. She was fine at dinner. Now she can barely finish a sentence.","reviewStatus":"clinician_reviewed","patient":{"name":"Amara","age":34,"sex":"Female","avatar":{"skinTone":"deep_brown","hair":"dark_braided_bun","outfit":"teal_blouse","ageCues":"young_adult"},"personality":"Usually composed; frightened now, speaking quickly in short, breathless phrases.","chiefComplaint":"Sudden breathlessness and pleuritic chest pain after a long-haul flight.","presentingTags":["Short of breath","Chest pain","Recent travel"],"initialExpression":"struggling_to_breathe"},"vitalsTimeline":[{"tMinute":0,"hr":118,"bp":"108/68","rr":26,"spo2":91,"temp":37.1},{"tMinute":8,"hr":130,"bp":"102/64","rr":30,"spo2":86,"temp":37.1},{"tMinute":18,"hr":142,"bp":"88/54","rr":35,"spo2":80,"temp":37}],"deteriorationRules":[{"id":"pe_no_oxygen","ifNotDoneBy":8,"action":"give_oxygen","effect":{"spo2":-5,"hr":12,"rr":4,"systolicBp":-6,"diastolicBp":-4},"alertLine":"Doctor, her saturation is falling — 86% and her heart rate is climbing.","source":"nurse","triggersEvent":"hypoxemia_worsens","lossAtMinute":18},{"id":"pe_no_monitoring","ifNotDoneBy":8,"action":"start_monitoring","effect":{"hr":4},"alertLine":"Can someone please keep the monitor on? I feel worse when I sit up.","source":"patient","triggersEvent":"unmonitored_deterioration"}],"actions":[{"id":"ask_onset","category":"ask","group":"Presenting complaint","label":"Ask how this began","timeCostMin":1,"moneyCost":0,"riskNote":"","result":{"type":"patient_reply","content":"It hit me all at once after dinner. The pain is sharp, especially when I breathe in — I feel like I''m going to die."},"variants":[{"when":{"vitals":{"spo2":{"below":88}}},"result":{"content":